import {STAGES,fold,safeUrl,queryFor,normalizeElement,uniqueLeads,toCsv,validateBackup} from './domain.mjs';
const $=id=>document.getElementById(id),STORAGE='orion-prospecta-v1',CACHE='orion-prospecta-cache-v1';
let cities=[],results=[],saved=[],visible=[],view='discover',busy=false,searched=false,lastSearch=0,selectedId='',map,markers,areaCircle,currentCity,noticeTimer,storageAvailable=true;
const categories={hairdresser:'Salão / barbearia',beauty:'Beleza',car_repair:'Oficina mecânica',car_parts:'Autopeças',tyres:'Pneus',restaurant:'Restaurante',cafe:'Café',fast_food:'Lanchonete',dentist:'Odontologia',doctors:'Consultório',clinic:'Clínica',pharmacy:'Farmácia',pet:'Pet shop',pet_grooming:'Banho e tosa',veterinary:'Veterinário',bakery:'Padaria',supermarket:'Supermercado',convenience:'Mercado',clothes:'Vestuário',accountant:'Contabilidade',lawyer:'Advocacia',hotel:'Hotel',guest_house:'Pousada',car_wash:'Lavação',fuel:'Posto de combustível'};
try{const raw=JSON.parse(localStorage.getItem(STORAGE)||'{"version":1,"leads":[]}');saved=validateBackup(raw);}catch{storageAvailable=false;}
function toast(message){clearTimeout(noticeTimer);$('status-message').textContent=message;$('status-message').classList.add('visible');noticeTimer=setTimeout(()=>$('status-message').classList.remove('visible'),6500);}
function persist(){try{localStorage.setItem(STORAGE,JSON.stringify({version:1,leads:saved}));storageAvailable=true;$('local-state').textContent='Salvo neste navegador · '+saved.length+' na lista';return true;}catch{storageAvailable=false;$('local-state').textContent='Sem espaço para salvar. Exporte um backup.';toast('Não foi possível salvar no navegador. Exporte um backup para guardar as alterações.');return false;}}
function node(tag,cls,text){const el=document.createElement(tag);if(cls)el.className=cls;if(text!==undefined)el.textContent=text;return el;}
function anchor(label,url,title){const a=node('a','',label);a.href=url;a.target='_blank';a.rel='noopener noreferrer';if(title)a.title=title;return a;}
function hasContact(l){return !!(l.phoneNumber||l.instagram||l.whatsapp);}
function merged(l){const own=saved.find(s=>s.id===l.id);return {...l,stage:own?.stage||'Revisar',verified:own?.verified||'unknown',followup:own?.followup||'',notes:own?.notes||''};}
function isSaved(id){return saved.some(l=>l.id===id);}
function linksFor(l){const wrap=node('div','contact-links');if(l.phoneNumber)wrap.append(anchor('☎ Telefone','tel:+'+l.phoneNumber,l.phone));if(l.whatsapp)wrap.append(anchor(l.whatsappConfirmed?'WhatsApp':'Testar WhatsApp',l.whatsapp,l.whatsappConfirmed?'WhatsApp informado na fonte':'Número de telefone; pode não ter WhatsApp'));if(l.instagram)wrap.append(anchor('Instagram',l.instagram));if(!hasContact(l))wrap.append(node('span','no-contact','Sem contato na fonte'));return wrap;}
function empty(title,body,loading=false){$('results').replaceChildren();const wrap=node('div','empty');wrap.append(node('div',loading?'loader':'empty-mark',loading?'':'⌖'),node('h2','',title),node('p','',body));$('results').append(wrap);}
function render(){
 $('found-count').textContent=results.length;$('saved-count').textContent=saved.length;$('discover-tab').setAttribute('aria-pressed',view==='discover');$('saved-tab').setAttribute('aria-pressed',view==='saved');$('stage-filter').hidden=view!=='saved';
 if(busy){empty('Consultando o mapa…','Buscando registros reais. Pode levar até 35 segundos.',true);$('result-caption').textContent='Busca em andamento';$('export-csv').disabled=true;return;}
 const text=fold($('name-filter').value),stage=$('stage-filter').value;
 visible=(view==='discover'?results:saved).map(merged).filter(l=>(!$('missing-only').checked||(!l.website&&l.verified!=='exists'))&&(!$('contact-only').checked||hasContact(l))&&(!text||fold(l.name).includes(text))&&(view!=='saved'||!stage||l.stage===stage));
 const sort=$('sort').value;visible.sort((a,b)=>sort==='name'?a.name.localeCompare(b.name,'pt-BR'):sort==='contact'?(Number(hasContact(b))-Number(hasContact(a))||a.distance-b.distance):a.distance-b.distance);
 $('result-caption').textContent=visible.length+' '+(visible.length===1?'negócio':'negócios')+(view==='saved'?' na sua lista':searched?' nos filtros':' para revisar');$('export-csv').disabled=!visible.length;
 $('results').replaceChildren();if(!visible.length){if(view==='saved')empty(saved.length?'Nenhum lead nesses filtros':'Sua próxima conversa começa aqui',saved.length?'Experimente mudar os filtros acima.':'Salve negócios da busca para organizar contatos, anotações e próximos passos.');else if(!searched)empty('Abra seu radar local','Escolha uma cidade e um nicho. Encontre negócios reais e revise quem pode precisar do seu trabalho.');else empty(results.length?'Nenhum resultado nesses filtros':'Poucos dados nesta região',results.length?'Experimente desmarcar “Sem site informado” ou “Com contato”.':'Tente outro nicho ou aumente o raio. Isso não significa que não existam empresas na região.');}
 for(const l of visible){const card=node('article','lead-card'+(l.id===selectedId?' is-selected':''));card.dataset.id=l.id;const top=node('div','card-top'),name=node('button','card-name',l.name);name.type='button';name.addEventListener('click',()=>focusLead(l));top.append(name,node('span','distance',l.distance.toLocaleString('pt-BR',{maximumFractionDigits:1})+' km'));card.append(top,node('div','card-category',categories[l.category]||l.category.replaceAll('_',' ')),node('p','card-address',l.address));const badges=node('div','badges');badges.append(node('span','badge '+(l.website?'badge-site':'badge-missing'),l.website?'Site informado':'Sem site informado'));if(isSaved(l.id))badges.append(node('span','badge badge-stage',l.stage));if(l.followup)badges.append(node('span','badge badge-date','Retorno: '+l.followup.split('-').reverse().join('/')));card.append(badges);const bottom=node('div','card-bottom'),save=node('button','save-button'+(isSaved(l.id)?' saved':''),isSaved(l.id)?'Editar lead ↗':'+ Salvar lead');save.type='button';save.addEventListener('click',()=>openLead(l));bottom.append(linksFor(l),save);card.append(bottom);$('results').append(card);}
 renderMarkers();
}
function setupMap(){if(!window.L){$('map-warning').hidden=false;return;}map=L.map('map',{zoomControl:false}).setView([-26.4851,-49.0713],12);L.control.zoom({position:'topright'}).addTo(map);markers=L.layerGroup().addTo(map);let supportsGL=false;try{const canvas=document.createElement('canvas');supportsGL=!!canvas.getContext('webgl2')||!!canvas.getContext('webgl');}catch{}if(supportsGL&&L.maplibreGL&&window.maplibregl){try{const layer=L.maplibreGL({style:'https://tiles.openfreemap.org/styles/positron',maxZoom:19}).addTo(map);const gl=layer.getMaplibreMap();let errors=0;gl.on('error',()=>{if(++errors>=4)$('map-warning').hidden=false;});gl.on('load',()=>{$('map-warning').hidden=true;});}catch{fallbackMap();}}else fallbackMap();}
async function fallbackMap(){try{const style=await fetch('https://tiles.openfreemap.org/styles/positron').then(r=>{if(!r.ok)throw new Error('Style unavailable');return r.json();});const source=Object.values(style.sources).find(s=>s.type==='vector'&&s.url);if(!source||new URL(source.url).hostname!=='tiles.openfreemap.org')throw new Error('Map source unavailable');const tilejson=await fetch(source.url).then(r=>{if(!r.ok)throw new Error('Tiles unavailable');return r.json();});const tile=tilejson.tiles?.[0];if(!tile||new URL(tile).hostname!=='tiles.openfreemap.org')throw new Error('Map tiles unavailable');const quiet={weight:0,opacity:0,fillOpacity:0,radius:0},area=(color,opacity=1)=>({fill:true,fillColor:color,fillOpacity:opacity,stroke:false,weight:0});const road=(p,z)=>({color:['motorway','trunk','primary'].includes(p.class)?'#d9cbb4':'#fff',weight:Math.max(1,(z-10)/2)+(['motorway','trunk','primary'].includes(p.class)?1:0),opacity:1});const styles={};for(const item of tilejson.vector_layers||[])styles[item.id]=quiet;Object.assign(styles,{water:area('#c8dfe0'),waterway:{color:'#c8dfe0',weight:2},landcover:area('#d7e4cd',.6),landuse:area('#e6e9dc',.6),park:area('#d5e5cb',.8),building:{...area('#d7dcd3'),stroke:true,color:'#c5cec2',weight:.4},transportation:road,boundary:{color:'#aebca6',weight:1,dashArray:'4 4',fill:false}});const layer=L.vectorGrid.protobuf(tile,{rendererFactory:L.canvas.tile,vectorTileLayerStyles:styles,interactive:false,maxNativeZoom:tilejson.maxzoom||14,maxZoom:19,attribution:'<a href="https://openfreemap.org">OpenFreeMap</a> &copy; <a href="https://openmaptiles.org">OpenMapTiles</a> · <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'}).addTo(map);layer.on('load',()=>{$('map-warning').hidden=true;});layer.on('tileerror',()=>{$('map-warning').hidden=false;});$('map').dataset.mode='simplified';}catch(error){console.warn('Map fallback:',error.message);$('map-warning').hidden=false;}}
function renderMarkers(){if(!map)return;markers.clearLayers();for(const l of visible){const marker=L.circleMarker([l.lat,l.lon],{radius:l.id===selectedId?9:6,color:'#fff',weight:2,fillColor:l.website?'#34765f':'#d08b3e',fillOpacity:.96}).addTo(markers);const content=node('div'),title=node('strong','',l.name),info=node('div','',l.website?'Site informado':'Sem site informado na fonte'),btn=node('button','map-popup-button',isSaved(l.id)?'Editar lead':'Salvar e revisar');btn.addEventListener('click',()=>openLead(l));content.append(title,info,btn);marker.bindPopup(content);marker.on('click',()=>{selectedId=l.id;const cards=$('results').querySelectorAll('.lead-card');for(const card of cards){card.classList.toggle('is-selected',card.dataset.id===l.id);if(card.dataset.id===l.id)card.scrollIntoView({block:'nearest',behavior:'smooth'});}});}}
function fitMap(){if(!map)return;const points=visible.map(l=>[l.lat,l.lon]);if(points.length)map.fitBounds(L.latLngBounds(points),{padding:[55,55],maxZoom:15});else if(currentCity)map.setView([currentCity.lat,currentCity.lon],12);}
function focusLead(l){selectedId=l.id;render();if(map){map.setView([l.lat,l.lon],16);for(const marker of markers.getLayers()){const p=marker.getLatLng();if(p.lat===l.lat&&p.lng===l.lon){marker.openPopup();break;}}}}
function openLead(l){selectedId=l.id;if(!isSaved(l.id)){saved.push({...l,stage:'Revisar',verified:'unknown',followup:'',notes:''});persist();}const own=saved.find(s=>s.id===l.id);$('lead-title').textContent=own.name;$('lead-address').textContent=own.address+' · '+own.city;$('lead-stage').value=own.stage;$('lead-verified').value=own.verified;$('lead-followup').value=own.followup;$('lead-notes').value=own.notes;const links=linksFor(own);links.append(anchor('Conferir presença ↗','https://www.google.com/search?q='+encodeURIComponent(own.name+' '+own.city+' site instagram')));if(own.website)links.append(anchor('Abrir site ↗',safeUrl(own.website)));links.append(anchor('Fonte OSM ↗',own.sourceUrl));$('lead-links').replaceChildren(links);$('lead-dialog').showModal();render();}
function setView(next){view=next;selectedId='';$('name-filter').value='';render();fitMap();}
function readCache(key){try{const cache=JSON.parse(localStorage.getItem(CACHE)||'[]');return cache.find(x=>x.key===key&&Date.now()-x.time<15*60*1000);}catch{return null;}}
function writeCache(key,elements){try{const old=JSON.parse(localStorage.getItem(CACHE)||'[]').filter(x=>x.key!==key&&Date.now()-x.time<15*60*1000).slice(0,2);localStorage.setItem(CACHE,JSON.stringify([{key,time:Date.now(),elements},...old]));}catch{/* A full cache must never block CRM saves. */try{localStorage.removeItem(CACHE);}catch{}}}
async function search(event){event?.preventDefault();if(busy)return;const typed=fold($('city').value),city=cities.find(c=>fold(c.name+' · '+c.uf)===typed);if(!city){toast('Selecione uma cidade da lista, incluindo a UF.');$('city').focus();return;}const niche=$('niche').value,radius=Number($('radius').value),key=city.id+':'+niche+':'+radius,cached=readCache(key);if(!cached&&Date.now()-lastSearch<10000){toast('Aguarde alguns segundos entre buscas.');return;}
 busy=true;$('search-button').disabled=true;render();currentCity=city;let partial=false;
 try{let elements;if(cached)elements=cached.elements;else{lastSearch=Date.now();const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),35000);try{const response=await fetch('https://overpass-api.de/api/interpreter',{method:'POST',body:new URLSearchParams({data:queryFor(niche,city.lat,city.lon,radius)}),signal:controller.signal,referrerPolicy:'strict-origin-when-cross-origin'});if(!response.ok)throw new Error(response.status===429?'O serviço está ocupado. Aguarde e tente mais tarde.':'O serviço de mapas não respondeu ('+response.status+'). Tente novamente mais tarde.');const data=await response.json();if(!Array.isArray(data.elements))throw new Error('A fonte retornou dados inesperados.');elements=data.elements;partial=!!data.remark;if(!partial)writeCache(key,elements);}finally{clearTimeout(timer);}}
 results=uniqueLeads(elements.map(e=>normalizeElement(e,city)).filter(Boolean));searched=true;view='discover';$('map-caption').textContent=city.name+' · '+city.uf+' · raio '+radius+' km';if(map){if(areaCircle)map.removeLayer(areaCircle);areaCircle=L.circle([city.lat,city.lon],{radius:radius*1000,color:'#65895d',weight:1,dashArray:'5 7',fillOpacity:.025,interactive:false}).addTo(map);map.setView([city.lat,city.lon],radius<=3?13:radius<=5?12:radius<=10?11:10);}toast(partial?'A fonte retornou uma busca parcial. Reduza o raio para tentar novamente.':cached?'Resultados do cache recente (até 15 min).':results.length+' negócios encontrados. Confira os dados antes de abordar.');
 }catch(error){toast(error.name==='AbortError'?'A busca demorou demais. Reduza o raio ou tente mais tarde.':error.message||'Não foi possível buscar. Tente mais tarde.');}finally{busy=false;$('search-button').disabled=false;render();}
}
function download(name,body,type){const url=URL.createObjectURL(new Blob([body],{type})),a=node('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
for(const stage of STAGES){$('lead-stage').append(new Option(stage,stage));$('stage-filter').append(new Option(stage,stage));}
$('search-form').addEventListener('submit',search);$('discover-tab').addEventListener('click',()=>setView('discover'));$('saved-tab').addEventListener('click',()=>setView('saved'));
for(const id of ['missing-only','contact-only','stage-filter','sort'])$(id).addEventListener('change',render);$('name-filter').addEventListener('input',render);$('fit-map').addEventListener('click',fitMap);
$('lead-close').addEventListener('click',()=>$('lead-dialog').close());$('lead-form').addEventListener('submit',e=>{e.preventDefault();const own=saved.find(s=>s.id===selectedId);if(!own)return;Object.assign(own,{stage:$('lead-stage').value,verified:$('lead-verified').value,followup:$('lead-followup').value,notes:$('lead-notes').value.trim()});const ok=persist();$('lead-dialog').close();render();if(ok)toast('Lead atualizado. Próximo passo registrado.');});
$('lead-remove').addEventListener('click',()=>{saved=saved.filter(s=>s.id!==selectedId);persist();$('lead-dialog').close();render();toast('Removido da sua lista. O negócio continua disponível nas buscas.');});
$('export-csv').addEventListener('click',()=>{if(visible.length)download('prospecta-'+new Date().toISOString().slice(0,10)+'.csv',toCsv(visible),'text/csv;charset=utf-8');});
$('backup').addEventListener('click',()=>download('prospecta-backup-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify({version:1,exportedAt:new Date().toISOString(),attribution:'© colaboradores do OpenStreetMap, ODbL',leads:saved},null,2),'application/json'));
$('restore').addEventListener('click',()=>$('restore-file').click());$('restore-file').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{if(file.size>10*1024*1024)throw new Error('O arquivo excede 10 MB.');const imported=validateBackup(JSON.parse(await file.text()));let added=0;for(const l of imported){if(!isSaved(l.id)){saved.push(l);added++;}}const ok=persist();setView('saved');if(ok)toast(added+' leads importados. Os registros que já existiam foram preservados.');}catch(error){toast(error.message||'Arquivo inválido.');}finally{e.target.value='';}});
for(const id of ['help-open','about-data'])$(id).addEventListener('click',()=>$('help-dialog').showModal());for(const id of ['help-close','help-done'])$(id).addEventListener('click',()=>$('help-dialog').close());
$('city').addEventListener('input',()=>{const q=fold($('city').value);$('cities-list').replaceChildren(...cities.filter(c=>fold(c.name+' '+c.uf).includes(q)).slice(0,15).map(c=>new Option(c.name+' · '+c.uf)));});
setupMap();render();if(!storageAvailable){$('local-state').textContent='Não foi possível ler a lista local. Guarde seus backups.';toast('Armazenamento local indisponível ou backup local inválido.');}
try{const response=await fetch(new URL('./cities.json',import.meta.url));if(!response.ok)throw new Error();cities=await response.json();currentCity=cities.find(c=>c.name==='Jaraguá do Sul'&&c.uf==='SC');$('cities-list').replaceChildren(...cities.filter(c=>['Jaraguá do Sul','Joinville','Florianópolis','São Paulo','Curitiba'].includes(c.name)).slice(0,15).map(c=>new Option(c.name+' · '+c.uf)));$('city').disabled=false;$('search-button').disabled=false;}catch{toast('Não foi possível carregar as cidades. Recarregue a página para tentar novamente.');}
